function inputKey(d) {
  return [
    d.kind,
    d.classId,
    d.lid,
    d.pid || "",
    d.uid || "",
    d.sid,
    d.field,
  ].join("|");
}

function draftStorageKey() {
  return draftBaseKey() + "." + documentToken;
}

function isSupportedGradeDraft(item) {
  return EduGradeDrafts.isSupportedGradeDraft(item);
}

async function persistedGradeDrafts(prefix) {
  const records = new Map();
  const add = (key, raw) => {
    const entry = {
      key,
      entries: Array.isArray(raw) ? raw : raw?.entries,
      generation: Array.isArray(raw) ? 0 : Number(raw?.generation || 0),
      updatedAt: Array.isArray(raw) ? "" : (raw?.updatedAt ?? ""),
    };
    if (
      !Number.isSafeInteger(entry.generation) ||
      entry.generation < 0 ||
      typeof entry.updatedAt !== "string"
    )
      throw Object.assign(
        Error(
          "نسخه یا زمان پیش‌نویس معتبر نیست؛ نسخهٔ خام را برای بررسی دریافت کنید.",
        ),
        { code: "GRADE_DRAFT_INVALID" },
      );
    const previous = records.get(key);
    if (
      !previous ||
      entry.generation > previous.generation ||
      (entry.generation === previous.generation &&
        entry.updatedAt > previous.updatedAt)
    )
      records.set(key, entry);
  };
  let unreadable = false,
    unavailable = false;
  try {
    for (const key of Object.keys(localStorage).filter(
      (key) =>
        key === prefix ||
        key.startsWith(prefix + ".") ||
        (prefix.endsWith(".") && key.startsWith(prefix)),
    )) {
      let raw;
      try {
        raw = localStorage.getItem(key);
      } catch {
        unavailable = true;
        continue;
      }
      try {
        add(key, JSON.parse(raw));
      } catch {
        unreadable = true;
      }
    }
  } catch {
    unavailable = true;
  }
  if (connection?.objectStoreNames.contains("drafts")) {
    const tx = connection.transaction("drafts", "readonly");
    const rows = await requestPromise(
      tx.objectStore("drafts").index("workspace").getAll(workspace.id),
    );
    for (const row of rows)
      if (
        row.key === prefix ||
        row.key.startsWith(prefix + ".") ||
        (prefix.endsWith(".") && row.key.startsWith(prefix))
      )
        add(row.key, row);
  }
  if (unreadable)
    throw Object.assign(
      Error(
        "خواندن یکی از پیش‌نویس‌های قبلی انجام نشد؛ نسخهٔ قدیمی جایگزین آن نشد. نسخهٔ خام را برای بررسی دریافت کنید.",
      ),
      { code: "GRADE_DRAFT_INVALID" },
    );
  if (unavailable && !records.size)
    throw Error("خواندن پیش‌نویس‌های قبلی انجام نشد.");
  return [...records.values()];
}

function storeDrafts() {
  if (!workspace || resetBusy || connectionRetired) return Promise.resolve();
  const key = draftStorageKey(),
    entry = {
      key,
      workspace: workspace.id,
      owner: documentToken,
      generation: draftGeneration,
      entries: clone([...drafts.values()]),
      updatedAt: new Date().toISOString(),
    };
  let localFailure = false;
  try {
    const current = JSON.parse(localStorage.getItem(key) || "null");
    if (
      current &&
      !Array.isArray(current) &&
      Number(current.generation) > draftGeneration
    )
      return Promise.resolve();
    localStorage.setItem(key, JSON.stringify(entry));
  } catch {
    localFailure = true;
  }
  const targetConnection = connection,
    sourceInstallation =
      typeof installationToken === "undefined" ? "" : installationToken;
  draftWritesPending++;
  const operation = draftWriter
    .catch(() => {})
    .then(async () => {
      if (connectionRetired) return;
      if (!targetConnection?.objectStoreNames.contains("drafts"))
        throw Error("ذخیره پایدار پیش‌نویس در دسترس نیست.");
      let tx;
      try {
        tx = targetConnection.transaction(["records", "drafts"], "readwrite", {
          durability: "strict",
        });
      } catch (error) {
        if (!(error instanceof TypeError)) throw error;
        tx = targetConnection.transaction(["records", "drafts"], "readwrite");
      }
      const done = transactionDone(tx),
        store = tx.objectStore("drafts"),
        request = store.get(key),
        epoch = tx
          .objectStore("records")
          .get(
            typeof RESET_RECORD_KEY === "undefined"
              ? "@installation-reset"
              : RESET_RECORD_KEY,
          );
      let remaining = 2,
        failure;
      const persist = () => {
        if (--remaining) return;
        try {
          if ((epoch.result?.value?.token || "") !== sourceInstallation) {
            const error = Error(
              "اطلاعات سیستم در پنجرهٔ دیگری جایگزین شده است؛ پیش‌نویس قدیمی ثبت نشد.",
            );
            error.code = "INSTALLATION_CHANGED";
            throw error;
          }
          if (!request.result || request.result.generation <= entry.generation)
            store.put(entry);
        } catch (error) {
          failure = error;
          try {
            tx.abort();
          } catch {}
        }
      };
      request.onsuccess = persist;
      epoch.onsuccess = persist;
      try {
        await done;
      } catch (error) {
        throw failure || error;
      }
      draftRecoveryFailed = false;
      if (localFailure && entry.entries.length)
        setStatus("پیش‌نویس پایدار محفوظ است؛ در انتظار ثبت نمره.", "pending");
    })
    .catch((error) => {
      if (error.code === "INSTALLATION_CHANGED")
        try {
          // An old tab may receive the reset notification after this transaction.
          // Remove only our exact stale local copy; never a newer local edit.
          if (localStorage.getItem(key) === JSON.stringify(entry))
            localStorage.removeItem(key);
        } catch {}
      draftRecoveryFailed = true;
      setStatus(
        "ذخیره پایدار پیش‌نویس انجام نشد؛ تا ثبت موفق نمره صفحه را نبندید. " +
          error.message,
        "error",
      );
      throw error;
    })
    .finally(() => {
      draftWritesPending--;
    });
  draftWriter = operation;
  operation.catch(() => {});
  return operation;
}

async function loadDrafts() {
  const sourceConnection = connection,
    sourceInstallation =
      typeof installationToken === "undefined" ? "" : installationToken;
  drafts.clear();
  try {
    const base = draftBaseKey();
    const records = (await persistedGradeDrafts(base)).filter(
      (row) => row.key === base || row.key.startsWith(base + "."),
    );
    records.sort(
      (a, b) =>
        b.generation - a.generation || b.updatedAt.localeCompare(a.updatedAt),
    );
    const saved = records[0];
    // Validate only the selected generation; an older row must never replace it.
    EduGradeDrafts.assertEntries(saved ? saved.entries : []);
    draftGeneration = (saved?.generation || 0) + 1;
    for (const original of saved?.entries || []) {
      const stale =
        !Number.isInteger(original.baseRevision) ||
        original.baseRevision !== workspace.revision;
      const item = stale
        ? {
            ...original,
            review: true,
            error:
              "اطلاعات از زمان این پیش‌نویس تغییر کرده یا نسخه مرجع نامعلوم است؛ نیازمند بررسی",
          }
        : original;
      drafts.set(inputKey(item), item);
    }
    await storeDrafts();
    await pruneGradeDrafts(
      records.filter((row) => row.generation < draftGeneration - 1),
      sourceConnection,
      sourceInstallation,
    );
  } catch (error) {
    draftRecoveryFailed = true;
    setStatus(
      "پیش‌نویس قبلی خوانده نشد؛ داده اصلی محفوظ است. " + error.message,
      "error",
    );
  }
}

async function pruneGradeDrafts(rows, sourceConnection, sourceInstallation) {
  if (!rows.length) return;
  const tx = sourceConnection.transaction(["records", "drafts"], "readwrite"),
    done = transactionDone(tx),
    store = tx.objectStore("drafts"),
    epoch = tx
      .objectStore("records")
      .get(
        typeof RESET_RECORD_KEY === "undefined"
          ? "@installation-reset"
          : RESET_RECORD_KEY,
      );
  let failure;
  const abort = (error) => {
    failure = error;
    try {
      tx.abort();
    } catch {}
  };
  epoch.onsuccess = () => {
    try {
      if ((epoch.result?.value?.token || "") !== sourceInstallation) {
        const error = Error(
          "اطلاعات سیستم در پنجرهٔ دیگری جایگزین شده است؛ پیش‌نویس‌های بازیابی‌شده پاک نشدند.",
        );
        error.code = "INSTALLATION_CHANGED";
        throw error;
      }
      for (const row of rows) {
        const same = (raw) =>
          !!raw &&
          (Array.isArray(raw) ? 0 : Number(raw.generation || 0)) ===
            row.generation &&
          (raw.updatedAt || "") === row.updatedAt &&
          JSON.stringify(Array.isArray(raw) ? raw : raw.entries || []) ===
            JSON.stringify(row.entries);
        const request = store.get(row.key);
        request.onsuccess = () => {
          try {
            if (same(request.result)) store.delete(row.key);
            try {
              if (same(JSON.parse(localStorage.getItem(row.key) || "null")))
                localStorage.removeItem(row.key);
            } catch {}
          } catch (error) {
            abort(error);
          }
        };
      }
    } catch (error) {
      abort(error);
    }
  };
  try {
    await done;
  } catch (error) {
    throw failure || error;
  }
}
