async function bootstrapV24() {
  document.getElementById("app").innerHTML =
    '<div class="card" role="status">در حال خواندن امن اطلاعات…</div>';
  try {
    await claimTab();
    connection = await openDatabase();
    connectionRetired = false;
    const resetMarker = await readRecord("records", RESET_RECORD_KEY);
    installationToken = resetMarker?.value?.token || "";
    if (!resetMarker)
      try {
        installationToken = localStorage.getItem(RESET_EPOCH_KEY) || "";
      } catch {}
    if (resetMarker?.value?.phase === "cleanup") {
      try {
        await completeResetCleanup(connection, resetMarker);
        await claimTab();
      } catch (error) {
        forgetInstallation();
        resetScreen(
          "اطلاعات بانک آماده است؛ پاک‌سازی حافظه مرورگر هنوز کامل نشده است. برای ادامه، دوباره بارگذاری کنید. " +
            error.message,
        );
        return;
      }
    }
    let periods = await allFrom("catalog"),
      initialWorkspaceId = null;
    if (!periods.length) {
      const raw = resetMarker ? null : localStorage.getItem(STORAGE_KEY);
      let data;
      if (raw) {
        const original = JSON.parse(raw);
        data = normalizeDB(original, { legacy: true });
        data.settings.academicTerm =
          original.settings?.academicTerm || "سوابق پیشین";
        await putBackup(original, "انتقال نسخه قبلی", null);
      } else data = v24DefaultDB();
      const initialId = resetMarker
        ? "reset-" + resetMarker.value.token
        : "initial";
      let created;
      try {
        created = await installWorkspace(data, {
          id: initialId,
          year: data.settings.academicYear,
          term: data.settings.academicTerm,
        });
      } catch (error) {
        created = await readRecord("catalog", initialId);
        if (!created) throw error;
      }
      periods = [created];
      initialWorkspaceId = created.id;
      const check = await readWorkspace(created.id);
      if (!check.data) throw Error("بازخوانی انتقال تأیید نشد.");
      if (raw) {
        localStorage.removeItem(STORAGE_KEY);
        storageSnapshot = null;
      }
    }
    const normalizedYears = await synchronizeAcademicYearsForRead();
    if (normalizedYears.changed.length) {
      periods = await allFrom("catalog");
      for (const change of normalizedYears.changed) broadcast(change);
    }
    const preferred = preferredPeriod();
    workspace = selectAcademicWorkspace(
      periods,
      academicBootstrapPreferences(periods, {
        year: preferredAcademicYear(),
        preferredId: preferred,
        resetMarker,
        initialWorkspaceId,
      }),
    );
    const annual = globalThis.EduAnnualModules
      ? await synchronizeAnnualForRead(workspace.id)
      : null;
    const loaded = await readWorkspaceSnapshot(workspace.id);
    workspace = loaded.period;
    db = loaded.data;
    committed = loaded.records;
    await synchronizeYearNotesScope();
    storageBlocked = false;
    storageProblem = "";

    try {
      rememberPeriod(workspace.id);
    } catch (ignore) {}
    setStatus("اطلاعات ذخیره‌شده خوانده شد.", "saved");
    const recoveryWarning = academicWorkspaceRecoveryWarning(
      workspace,
      periods,
    );
    if (recoveryWarning) setStatus(recoveryWarning, "pending");
    for (const change of annual?.changed || [])
      broadcast({ ...change, annualModular: true });
    if (annual?.conflicts.length)
      setStatus(
        "اطلاعات قدیمی این سال نیاز به بررسی دارد: " +
          annual.conflicts[0].message,
        "error",
      );
    hydrateReportNotes(workspace);
    await loadDrafts();
    ready = true;
    render();
    await recoverDrafts();
    if (navigator.storage?.persist) navigator.storage.persist().catch(() => {});
    await restoreSingleFile();
  } catch (error) {
    blocked = true;
    storageBlocked = true;
    storageProblem = error.message;
    document.getElementById("app").innerHTML =
      '<div class="card" role="alert"><h2>خواندن اطلاعات انجام نشد</h2><p>' +
      esc(error.message) +
      '</p><button data-workspace-action="raw-recovery">دریافت نسخه قبلی</button><button data-workspace-action="choose-import">بازیابی پشتیبان سالم</button></div>';
  }
}
